package com.zpantry.pantry.domain;import com.zpantry.common.persistence.BaseEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="user_pantry_items")public class PantryItemEntity extends BaseEntity{@Column(name="user_id")public UUID userId;@Column(name="ingredient_id")public UUID ingredientId;@Column(precision=18,scale=4)public BigDecimal quantity;public String unit;@Column(name="expired_at")public Instant expiredAt;@Column(name="storage_location")public String storageLocation;public String note;protected PantryItemEntity(){}public PantryItemEntity(UUID u,UUID i){userId=u;ingredientId=i;}}
